run_ten_at_e500:		; The ten objects at 0xE500: adds their speed to them, checks whether they collide and switches off the ones that go off screen
	ld ix,0e500h		;65dc
	ld b,00ah		;65e0   ; Ten objects
L_65E2:
	ld a,(ix+000h)		;65e2
	and a			;65e5
	jr z,L_660B		;65e6
	call 05f7ch		;65e8   ; Adds their speed to them, and returns whether they are still inside
	jr c,L_65F1		;65eb
	ld (ix+000h),000h		;65ed
L_65F1:
	call 098ach		;65f1   ; And bank 2 checks whether they have collided with anything
	jr c,L_6604		;65f4
	ld a,(ix+004h)		;65f6   ; Past Y 0xB0 or X 0xF0, they are gone
	cp 0b0h		;65f9
	jr nc,L_6604		;65fb
	ld a,(ix+006h)		;65fd
	cp 0f0h		;6600
	jr c,L_660B		;6602
