	ld a,(0e1c0h)		;6613   ; With the screen stopped there is no shooting
	and a			;6616
	ret nz			;6617
	ld a,e			;6618
	add a,008h		;6619
	ld e,a			;661b
	ld a,(0e111h)		;661c   ; The difficulty times two plus 0x50...
	add a,a			;661f
	add a,050h		;6620
