; ----------------------------------------------------------------------
; THE ENEMY'S AIM GETS WORSE ON PURPOSE... WITH THE R REGISTER
; From difficulty 7 upwards, the enemy's shot does NOT go straight at the
; ship: it gets an error taken from the Z80's R register, four bits, which
; is sometimes added and sometimes subtracted depending on bit 6 of that
; same read. Below difficulty 7 the shot is clean. It is the fourth time
; the cartridge uses the refresh register as a number generator.
; ----------------------------------------------------------------------
aim_at_ship:		; Works out which way the shot goes; from difficulty 7 upwards it adds an error from the R register
	call measure_distance_to_ship		;6677
	ld a,(0ec17h)		;667a
	ld e,a			;667d
	ld a,(0e111h)		;667e   ; Below difficulty 7, no error
	cp 007h		;6681
	jr c,get_both_speeds		;6683
	ld a,r		;6685   ; The R register: four bits of error
	ld b,a			;6687
	and 00fh		;6688
	bit 6,b		;668a   ; And its bit 6 decides whether it is added or subtracted
	jr z,L_6697		;668c   ; Bit 6 decides the sign of the error
	ld b,a			;668e
	ld a,c			;668f
	sub b			;6690
	jr nc,L_6694		;6691
	xor a			;6693
L_6694:
	ld e,a			;6694
	jr get_both_speeds		;6695
L_6697:
	add a,e			;6697
	cp 03fh		;6698   ; Capped at 0x3F
	jr c,L_669E		;669a
	ld a,03fh		;669c
L_669E:
	ld e,a			;669e

