	sub 03fh		;66a2   ; 0x3F minus the index: the complementary angle
	neg		;66a4
	ld hl,06853h		;66a6   ; The table at 0x6853, read from both ends
	push hl			;66a9   ; The table, from both ends
	add hl,de			;66aa
	ld c,(hl)			;66ab
	pop hl			;66ac
	ld e,a			;66ad
	add hl,de			;66ae
	ld a,(hl)			;66af
	ld (0ec16h),a		;66b0
	ld e,c			;66b3
	call times_speed		;66b4   ; Times the speed
	ld a,(0ec10h)		;66b7   ; 0xEC10 says whether X goes the other way
	and a			;66ba
	call nz,change_sign		;66bb
	ld (0ec12h),de		;66be   ; 0xEC12: the vertical speed, the one from the difference in rows
	ld a,(0ec16h)		;66c2
	ld e,a			;66c5
	call times_speed		;66c6
	ld a,(0ec11h)		;66c9
	and a			;66cc
	call nz,change_sign		;66cd
	ld (0ec14h),de		;66d0   ; And 0xEC14: the horizontal one
	ret			;66d4
