; ----------------------------------------------------------------------
; PUTTING A NEW OBJECT ON THE SCREEN
; This is the most called routine in the bank: all the enemy movers use it
; to release a shot, an explosion or a new enemy. It is entered with A =
; the type, DE = where it goes and C = an adjustment, and it looks for a
; free slot in the object table, fills it with the record that belongs to
; the type (four bytes from the table at 0x6BA3) and bumps the live count.
; Three types break the rule: 0x1E needs THREE consecutive slots (which
; is why 0x6AA1 looks for three consecutive free slots and adds two to the
; count), 0x0E goes to another table (the one at 0xE460, eight slots of
; 0x20 bytes counted backwards) and the rest to the one at 0xE300, twelve
; slots.
; ----------------------------------------------------------------------
spawn_object:		; Looks for a free slot and sets up there an object of type A, at position DE
	ld (0ec19h),de		;6a72   ; Where it goes, noted in 0xEC19
	ld (0e120h),a		;6a76   ; And the type, in 0xE120
	xor a			;6a79
	ld (0e124h),a		;6a7a
	ld a,c			;6a7d
	ld (0e121h),a		;6a7e
	ld a,(0e120h)		;6a81
	cp 01eh		;6a84   ; Type 0x1E takes three slots
	jp z,find_three_consecutive_slots		;6a86
	sub 00eh		;6a89   ; And 0x0E goes to the other table
	jr z,search_other_table		;6a8b
	ld hl,0e300h		;6a8d   ; The twelve slots at 0xE300, 0x20 apart
	ld b,00ch		;6a90
	ld de,00020h		;6a92
	xor a			;6a95
	jr find_free_slot		;6a96
find_three_consecutive_slots:		; The big object needs three consecutive free slots; if there are none, it does not come out
	ld hl,0e300h		;6a98
	ld c,00ch		;6a9b
	ld de,00020h		;6a9d
	xor a			;6aa0
L_6AA1:
	ld b,003h		;6aa1   ; Three in a row
L_6AA3:
	cp (hl)			;6aa3   ; Three free slots in a row
	add hl,de			;6aa4   ; Compared with zero: free slot
	jr nz,L_6AAE		;6aa5   ; Thirty-two bytes: the next slot
	dec b			;6aa7
	jr z,L_6AB2		;6aa8
	dec c			;6aaa
	jr nz,L_6AA3		;6aab
	ret			;6aad
L_6AAE:
	dec c			;6aae
	jr nz,L_6AA1		;6aaf
	ret			;6ab1
L_6AB2:
	ld de,0ffa0h		;6ab2   ; Go back to the first of the three
	add hl,de			;6ab5
	exx			;6ab6
	ld hl,0e126h		;6ab7   ; And two more in the live count: it is three slots
	inc (hl)			;6aba
	inc (hl)			;6abb
	exx			;6abc
	jr set_up_object		;6abd
search_other_table:		; Type 0x0E lives at 0xE460, eight slots counted backwards
	ld de,0ffe0h		;6abf   ; Type 0x0E goes to the table at 0xE460
	ld b,008h		;6ac2
	ld hl,0e460h		;6ac4   ; Eight slots counting backwards
find_free_slot:		; The first one with its first byte at zero
	cp (hl)			;6ac7
	jr z,set_up_object		;6ac8
	add hl,de			;6aca
	djnz find_free_slot		;6acb
	ret			;6acd
set_up_object:		; Fills the slot: type, counters to zero, the position, and the four bytes from the table at 0x6BA3
	ld de,(0ec19h)		;6ace   ; The position, which was parked in 0xEC19
	exx			;6ad2
