	exx			;6ad7
	push hl			;6ad8
	pop ix		;6ad9
	ld a,(0e120h)		;6adb
	ld (0e124h),a		;6ade
	ld (ix+01bh),003h		;6ae1   ; Byte 27 to three
	ld (hl),a			;6ae5
	inc l			;6ae6
	xor a			;6ae7
	ld (hl),a			;6ae8
	inc l			;6ae9
	ld (hl),a			;6aea
	inc l			;6aeb
	inc l			;6aec
	ld (hl),e			;6aed   ; The Y goes to byte 4...
	inc l			;6aee
	inc l			;6aef
	ld (hl),d			;6af0   ; ...and the X to byte 6
	ld de,00005h		;6af1
	add hl,de			;6af4
	ld de,06ba3h		;6af5   ; The table at 0x6BA3: four bytes per type
	ld a,(0e120h)		;6af8
