	ld a,(0e120h)		;6b12
	cp 00dh		;6b15
	jr nz,L_6B1B		;6b17
	ld b,006h		;6b19
L_6B1B:
	ld (ix+00dh),b		;6b1b
L_6B1E:
	inc e			;6b1e
