	xor a			;6b26
	ld (de),a			;6b27
	ld a,(0e120h)		;6b28   ; Types 2, 0x0A and 0x0C carry two more bytes
	cp 002h		;6b2b   ; The type, again
	jr z,L_6B37		;6b2d
	cp 00ah		;6b2f
	jr z,L_6B37		;6b31
	cp 00ch		;6b33
	jr nz,L_6B3F		;6b35
L_6B37:
	ld a,001h		;6b37
	ld (de),a			;6b39
	inc de			;6b3a
	ld a,(0e166h)		;6b3b   ; 0xE166
	ld (de),a			;6b3e
L_6B3F:
	ld a,(0e120h)		;6b3f   ; And each type finishes its record on its own: thirty-one exits
	dec a			;6b42
	call 04067h		;6b43

