finish_type_1:		; Gives it the speed halved and the drawing that bits 5 and 6 of 0xE122 say
	call 09181h		;6c23
	sra a		;6c26   ; Halved, keeping the sign
	ld (ix+010h),a		;6c28
	ld a,(0e122h)		;6c2b
	ld c,a			;6c2e
	xor a			;6c2f
	bit 5,c		;6c30   ; Bit 5 of 0xE122...
	jr z,L_6C36		;6c32
	ld a,002h		;6c34
L_6C36:
	bit 6,c		;6c36   ; ...and bit 6: between the two they choose one of four drawings
	jr nz,L_6C3B		;6c38
	inc a			;6c3a
L_6C3B:
	ld (ix+017h),a		;6c3b
	ret			;6c3e
finish_type_7:		; The hatch enemy: it goes out to one side or the other, depending on bit 0 of the type of whoever releases it, and with no vertical speed
	ld a,(0e123h)		;6c3f
	ld de,00400h		;6c42   ; 0x0400 to the right...
	rra			;6c45
	jr nc,L_6C4B		;6c46
	ld de,0fc00h		;6c48   ; ...or 0xFC00 to the left
L_6C4B:
	call set_vertical_speed		;6c4b
	ld de,00000h		;6c4e
	jr set_horizontal_speed		;6c51
finish_with_slow_aim:		; Base speed 0x50 plus twice the difficulty
	ld c,050h		;6c53
	jr L_6C59		;6c55
finish_with_aim:		; The same but with base 0x60
	ld c,060h		;6c57
L_6C59:
	ld a,(0e111h)		;6c59   ; The difficulty times two, added to the base
	add a,a			;6c5c
	add a,c			;6c5d
	ld (0e110h),a		;6c5e
aim_from_where_it_is:		; With the object's position, works out the two speeds towards the ship and stores them
	ld e,(ix+004h)		;6c61
	ld d,(ix+006h)		;6c64
	call aim_at_ship		;6c67
	ld de,(0ec12h)		;6c6a   ; The vertical speed...
	call set_vertical_speed		;6c6e
	ld de,(0ec14h)		;6c71   ; ...and the horizontal one
	jr set_horizontal_speed		;6c75
finish_type_15:		; Copies the speeds from 0xE142 and 0xE144, and gives it six to eight of counter with the R register
	ld hl,(0e142h)		;6c77   ; The speed the background carries
	ld (ix+007h),l		;6c7a
	ld (ix+008h),h		;6c7d
	ld hl,(0e144h)		;6c80
	ld (ix+009h),l		;6c83
	ld (ix+00ah),h		;6c86
	ld a,(0e061h)		;6c89   ; In stage 4 the scroll goes the other way
	cp 004h		;6c8c
	ld hl,00088h		;6c8e
	jr nz,L_6C96		;6c91
	ld hl,0ff78h		;6c93
L_6C96:
	ld (ix+017h),l		;6c96
	ld (ix+018h),h		;6c99
	ld a,r		;6c9c   ; The R register again: six or eight
	and 002h		;6c9e
	add a,006h		;6ca0
	ld (ix+00dh),a		;6ca2
	ret			;6ca5
finish_type_16:		; The drawing comes from 0xEC1B and it carries no speed
	ld a,(0ec1bh)		;6ca6
	ld (ix+00ch),a		;6ca9   ; The drawing, from byte 12
	ld de,00000h		;6cac
	call set_vertical_speed		;6caf   ; No speed
	jr set_horizontal_speed		;6cb2
set_both_speeds:		; The two speeds, crossed: first the Y one and then the X one
	ld de,(0ec14h)		;6cb4
	call set_horizontal_speed		;6cb8   ; First the Y one...
	ld de,(0ec12h)		;6cbb   ; ...and then the X one
set_vertical_speed:		; The object's vertical speed, in bytes 7 and 8
	ld (ix+007h),e		;6cbf
	ld (ix+008h),d		;6cc2
	ret			;6cc5
set_horizontal_speed:		; And the horizontal one, in bytes 9 and 10
	ld (ix+009h),e		;6cc6   ; Bytes 9 and 10
	ld (ix+00ah),d		;6cc9
	ret			;6ccc
dispatch_by_stage:		; Twelve exits, one per stage
	call check_which_music_plays		;6ccd
	ld a,(0e061h)		;6cd0
	dec a			;6cd3
	call 04067h		;6cd4

