L_6D76:
	ld a,(0e065h)		;6d76   ; 0xE065: the end-of-stage step
	dec a			;6d79
	jr z,wait_until_dead_and_clear		;6d7a
	dec a			;6d7c
	jr z,switch_on_boss_2		;6d7d
	dec a			;6d7f
	jr z,end_stage		;6d80
	ld a,(0e107h)		;6d82   ; Only on the steps with a column
	and a			;6d85
	ret z			;6d86
	call 0ab86h		;6d87
	jr advance_end_step		;6d8a
wait_until_dead_and_clear:		; The same, and it also clears 0xE972
