; ----------------------------------------------------------------------
; THE MUSIC CHANGES WITH THE DISTANCE TRAVELLED
; The music of each stage is not launched once: there is a list per stage
; (the table at 0x7056 says which one) with pairs [distance][what plays],
; and every frame it looks in it for the range the distance travelled falls
; in. If what comes out is different from what is already playing
; (0xE012), the change is noted.
; ----------------------------------------------------------------------
check_which_music_plays:		; Looks in the stage's list for the distance range it is in and, if the music is a different one, notes it
	ld a,(0e200h)		;7003   ; With the ship dead, no
	and a			;7006
	ret m			;7007
	ld a,(0e1c0h)		;7008   ; Nor with the screen stopped
	and a			;700b
	ret nz			;700c
	ld a,(0e114h)		;700d   ; Nor with 0xE114 set
	and a			;7010
	ret nz			;7011
	ld hl,0e113h		;7012   ; 0xE113: there is already a music change pending
	ld a,(hl)			;7015
	and a			;7016
	jr nz,start_noted_music		;7017
	ld a,(0e061h)		;7019
	ld hl,07056h		;701c   ; The table at 0x7056: one list per stage
	call 047aeh		;701f
	ld c,e			;7022
	ld b,d			;7023
	ld hl,(0e063h)		;7024   ; The distance travelled
L_7027:
	ld a,(bc)			;7027   ; Each row: two bytes of distance and one of music
	ld e,a			;7028
	inc bc			;7029
	ld a,(bc)			;702a
	ld d,a			;702b
	inc bc			;702c
	rst 20h			;702d   ; DCOMPR: the range is looked for
	jr c,L_7033		;702e
	inc bc			;7030
	jr L_7027		;7031
L_7033:
	ld a,(bc)			;7033
	ld hl,0e012h		;7034   ; If it is the one already playing, nothing is touched
	cp (hl)			;7037
	ret z			;7038
	ld (0e113h),a		;7039   ; And if not, it is noted in 0xE113
	ld a,(hl)			;703c
	and a			;703d
	ret z			;703e
	ld hl,06001h		;703f
	ld (0e044h),hl		;7042
	xor a			;7045
	ld (0e046h),a		;7046
	ret			;7049
start_noted_music:		; When the channel goes quiet, launches the music that was parked in 0xE113; 0xFF only clears it
	ld a,(0e012h)		;704a   ; Until the channel goes quiet, nothing changes
	and a			;704d
	ret nz			;704e
	ld a,(hl)			;704f
	cp 0ffh		;7050   ; 0xFF means silence
	ld (hl),000h		;7052
	ret z			;7054
	jp 049deh		;7055

