; ----------------------------------------------------------------------
; THE END-OF-STAGE BOSS, STEP BY STEP
; 0xE151 says there is a boss and 0xE152 which step it is on; within the
; step, 0xE190 keeps the core's count and 0xE153 the frames left. There
; are five steps: wait for the screen to be empty, bring the core down,
; wait for it to be killed, and the two exits.
; ----------------------------------------------------------------------
wait_until_nobody_left:		; Until the twenty-two slots are empty, the boss does not come in; then it loads its graphics and sets up the first piece
	ld hl,0e153h		;7c9d
	dec (hl)			;7ca0
	ret nz			;7ca1
	ld hl,0e300h		;7ca2   ; The twelve slots at 0xE300...
	ld de,00020h		;7ca5
	ld b,00ch		;7ca8
L_7CAA:
	ld a,(hl)			;7caa
	and a			;7cab
	jr nz,wait_one_more_frame		;7cac
	add hl,de			;7cae
	djnz L_7CAA		;7caf
	ld hl,0e500h		;7cb1   ; ...and the ten at 0xE500
	ld b,00ah		;7cb4
L_7CB6:
	ld a,(hl)			;7cb6
	and a			;7cb7
	jr nz,wait_one_more_frame		;7cb8
	add hl,de			;7cba
	djnz L_7CB6		;7cbb
	call 04a6dh		;7cbd   ; The explosion graphics
	xor a			;7cc0
	ld (0e155h),a		;7cc1   ; 0xE155 to zero: the core is still alive
	ld de,0e780h		;7cc4   ; The thirteen bytes from 0x7ED9 to 0xE780: the first piece
	ld hl,07ed9h		;7cc7
	ld bc,0000dh		;7cca
	ldir		;7ccd
	ld a,03ch		;7ccf   ; 0x3C frames
	ld (0e153h),a		;7cd1
next_core_step:		; 0xE190 + 1
	ld hl,0e190h		;7cd4
	inc (hl)			;7cd7
	ret			;7cd8
wait_one_more_frame:		; Something is still alive: look again on the next frame
	ld a,001h		;7cd9
	ld (0e153h),a		;7cdb
	ret			;7cde
core_enters:		; Every eight frames moves it eight points to the left until column 0x98, and there it stays 0x2D0 frames
	ld a,(0e003h)		;7cdf   ; One frame in eight
	and 007h		;7ce2
	ret nz			;7ce4
	ld hl,0e785h		;7ce5
	ld a,(hl)			;7ce8
	sub 008h		;7ce9   ; Eight points to the left
	ld (hl),a			;7ceb
	cp 098h		;7cec   ; Until column 0x98
	ret nz			;7cee
	ld hl,002d0h		;7cef   ; 0x2D0 frames standing still
	ld (0e153h),hl		;7cf2
	ld a,001h		;7cf5
	ld (0e786h),a		;7cf7
	jr next_core_step		;7cfa
core_waits:		; While it lives, it shoots and changes face according to the frames it has left: at 0x258 one, at 0x78 another
	ld a,(0e155h)		;7cfc   ; 0xE155 set: the core is already dead
	and a			;7cff
	jr nz,core_leaves		;7d00
	call move_boss		;7d02
	call core_shoots		;7d05
	ld hl,(0e153h)		;7d08
	dec hl			;7d0b
	ld (0e153h),hl		;7d0c
	ld de,00258h		;7d0f   ; With 0x258 frames to go, the first face
	rst 20h			;7d12
	jr nz,L_7D1A		;7d13
	xor a			;7d15
	ld (0e786h),a		;7d16
	ret			;7d19
L_7D1A:
	ld de,00078h		;7d1a   ; And with 0x78 to go, the second
	rst 20h			;7d1d
	jr nz,L_7D26		;7d1e
	ld a,001h		;7d20
	ld (0e786h),a		;7d22
	ret			;7d25
L_7D26:
	ld a,l			;7d26   ; With the count used up, the core leaves
	or h			;7d27
	ret nz			;7d28
core_leaves:		; Face 2, 0x28 frames and on to the next step
	ld a,002h		;7d29
	ld (0e786h),a		;7d2b
	ld a,028h		;7d2e   ; 0x28 frames
	ld (0e153h),a		;7d30
	jr next_core_step		;7d33
blow_up_core:		; Erases it, sets up the explosion, plays sound 0x3B and, if it was alive, collects 0x100
	ld hl,0e153h		;7d35
	dec (hl)			;7d38   ; 0xE153: the frames left
	ret nz			;7d39
	xor a			;7d3a
	ld (0e780h),a		;7d3b   ; 0xE780 to zero: the piece goes
	ld de,01808h		;7d3e
	call boss_cell		;7d41
	ex de,hl			;7d44
	call set_up_background_explosion		;7d45
	ld a,03bh		;7d48   ; Sound 0x3B
	call 049deh		;7d4a
	ld de,00100h		;7d4d   ; A hundred points, and only if the core was still alive
	ld a,(0e155h)		;7d50
	and a			;7d53
	call nz,055b4h		;7d54
	ld a,078h		;7d57   ; 0x78 frames
	ld (0e153h),a		;7d59   ; 0x78 frames
	jp next_core_step		;7d5c
end_boss:		; When the count runs out, 0xE150 to one: the stage can go on
	ld hl,0e153h		;7d5f
	dec (hl)			;7d62
	ret nz			;7d63
mark_boss_dead:		; 0xE150 to one
	ld a,001h		;7d64
	ld (0e150h),a		;7d66
	ret			;7d69
core_shoots:		; From the second loop onwards: every six of the player's shots it releases an aimed one, with speed 0x60
	ld a,(0e06ah)		;7d6a   ; Only from the second loop onwards
	and a			;7d6d
	ret z			;7d6e
	ld hl,0e78ch		;7d6f   ; 0xE78C: the ones it still has to release
	ld a,(hl)			;7d72
	and a			;7d73
	jr nz,L_7D7F		;7d74
	ld a,(0e008h)		;7d76   ; Bit 4 of what was just pressed: the player's fire
	and 010h		;7d79
	ret z			;7d7b
	ld (hl),006h		;7d7c   ; Six in one go
	ret			;7d7e
L_7D7F:
	dec (hl)			;7d7f
	ld a,(0e783h)		;7d80   ; Comes out 0x1C below the core and eight to its right
	add a,01ch		;7d83
	ld e,a			;7d85
	ld a,(0e785h)		;7d86
	add a,008h		;7d89
	ld d,a			;7d8b
	ld a,060h		;7d8c   ; Speed 0x60
	ld (0e110h),a		;7d8e
	push de			;7d91
	call aim_at_ship		;7d92
	pop de			;7d95
	ld hl,0e580h		;7d96   ; The six slots at 0xE580
	ld b,006h		;7d99
L_7D9B:
	ld a,(hl)			;7d9b
	and a			;7d9c
	jp z,set_up_shot		;7d9d
	ld a,020h		;7da0   ; Thirty-two bytes: the next one
	call 0405dh		;7da2   ; Thirty-two bytes: the next slot
	djnz L_7D9B		;7da5
	ret			;7da7
release_four_shots:		; Sets up the four slots at 0xE500 with the four shots, each with its offset from the table at 0x7E03
	ld a,(0e783h)		;7da8
	ld e,a			;7dab
	ld a,(0e785h)		;7dac
	ld d,a			;7daf
	exx			;7db0
	ld hl,07e03h		;7db1   ; The table at 0x7E03: where each one comes out
	exx			;7db4
	ld hl,0e500h		;7db5
	ld b,004h		;7db8   ; Four shots
set_up_one_of_four:		; Fills the slot and gives it the speed, which comes from the difficulty: the higher, the faster
	push de			;7dba
	ld (hl),001h		;7dbb   ; The slot is taken
	inc l			;7dbd   ; Four bytes further on
	inc l			;7dbe
	inc l			;7dbf
	inc l			;7dc0
	exx			;7dc1
	ld a,(hl)			;7dc2
	inc hl			;7dc3
	exx			;7dc4
	add a,e			;7dc5   ; The starting X...
	ld (hl),a			;7dc6   ; The X, and the byte next to it to zero
	inc l			;7dc7
	ld (hl),000h		;7dc8
	inc l			;7dca
	exx			;7dcb
	ld a,(hl)			;7dcc
	inc hl			;7dcd
	exx			;7dce
	add a,d			;7dcf   ; ...and the Y
	ld (hl),a			;7dd0
	inc l			;7dd1
	xor a			;7dd2   ; The counters, to zero
	ld (hl),a			;7dd3
	inc l			;7dd4
	ld (hl),a			;7dd5
	inc l			;7dd6
	push hl			;7dd7
	ld a,(0e111h)		;7dd8   ; The difficulty, negated
	inc a			;7ddb
	neg		;7ddc
	ld l,a			;7dde
	ld h,0ffh		;7ddf
	add hl,hl			;7de1   ; Times 0x20
	add hl,hl			;7de2
	add hl,hl			;7de3
	add hl,hl			;7de4
	add hl,hl			;7de5
	ld de,0fa00h		;7de6   ; Added to 0xFA00: the speed
	add hl,de			;7de9
	ex de,hl			;7dea
	pop hl			;7deb
	ld (hl),e			;7dec
	inc l			;7ded
	ld (hl),d			;7dee
	inc l			;7def
	ld a,b			;7df0   ; Bit 0 of the counter: one of two drawings
	and 001h		;7df1
	add a,002h		;7df3
	ld (hl),a			;7df5
	ld de,00010h		;7df6   ; Sixteen bytes further on, the mark
	add hl,de			;7df9
	ld (hl),001h		;7dfa   ; And the alive mark
	ld e,005h		;7dfc   ; Five more bytes: the next slot
	add hl,de			;7dfe
	pop de			;7dff
	djnz set_up_one_of_four		;7e00
	ret			;7e02

