move_boss:		; Chooses a drawing with the R register, decides which way to go depending on where the ship is, and keeps taking steps
	ld hl,0e781h		;7e0b   ; 0xE781: whether it is already moving
	ld a,(hl)			;7e0e
	and a			;7e0f
	jr nz,boss_takes_step		;7e10
	inc (hl)			;7e12
	ld a,r		;7e13   ; The R register: one of four drawings
	and 003h		;7e15
	ld (0e78bh),a		;7e17
	ld a,(0e783h)		;7e1a   ; 0x18 to the right of the boss
	add a,018h		;7e1d
	ld c,a			;7e1f
	ld a,(0e204h)		;7e20   ; The ship's row: that is the way it goes
	cp c			;7e23
	ld a,000h		;7e24
	jr c,L_7E29		;7e26
	inc a			;7e28
L_7E29:
	ld (0e787h),a		;7e29
	jp release_four_shots		;7e2c
boss_takes_step:		; Every so many frames (fewer the harder it is) it moves eight points, and after eleven steps it stops
	ld hl,0e78ah		;7e2f   ; 0xE78A: the frames left until the next step
	dec (hl)			;7e32
	ret nz			;7e33
	ld a,(0e111h)		;7e34   ; The difficulty: five, four or three frames per step
	ld c,005h		;7e37   ; The difficulty sets the frames per step
	cp 004h		;7e39
	jr c,L_7E43		;7e3b
	dec c			;7e3d
	cp 00ah		;7e3e
	jr c,L_7E43		;7e40
	dec c			;7e42
L_7E43:
	ld (hl),c			;7e43   ; And it is noted for the next step
	inc l			;7e44
	inc (hl)			;7e45
	ld a,(hl)			;7e46
	cp 00bh		;7e47   ; Eleven steps and it stops
	jr nz,L_7E50		;7e49
	xor a			;7e4b
	ld (0e781h),a		;7e4c
	ret			;7e4f
L_7E50:
	ld a,(0e787h)		;7e50   ; 0xE787 says which way
	ld b,a			;7e53
	ld c,0f8h		;7e54   ; Eight to the left or to the right
	and a			;7e56   ; Eight to one side or the other
	jr z,L_7E5B		;7e57
	ld c,008h		;7e59
L_7E5B:
	ld hl,0e783h		;7e5b
	ld a,(hl)			;7e5e
	add a,c			;7e5f
	ld (hl),a			;7e60
	ld c,001h		;7e61
	cp 010h		;7e63   ; Below X 0x10 it turns around
	jr c,L_7E6B		;7e65
	dec c			;7e67
	cp 078h		;7e68   ; And above 0x78, too
	ret c			;7e6a   ; It notes which way it is going
L_7E6B:
	ld a,c			;7e6b   ; And the side is saved
	ld (0e787h),a		;7e6c
	ret			;7e6f
draw_boss:		; Paints the three parts: the body of 0x0B by 8 characters, the eye and the mouth, each with its own table
	ld a,(0e780h)		;7e70
	dec a			;7e73
	ret nz			;7e74
	ld de,00000h		;7e75
	call boss_cell		;7e78
	jr c,L_7E86		;7e7b
	ld bc,00b08h		;7e7d   ; 0x0B wide by 8 high: the body
	ld de,07ee6h		;7e80
	call 0490ch		;7e83
L_7E86:
	ld de,00818h		;7e86   ; The eye, eight to the right and 0x18 lower
	call boss_cell		;7e89
	jr c,L_7EA3		;7e8c
	ld de,07f3eh		;7e8e
	ld a,(0e789h)		;7e91   ; 0xE789 chooses one of the eye drawings
	rra			;7e94
	and 00eh		;7e95
	ld c,a			;7e97
	add a,a			;7e98
	add a,c			;7e99   ; Times three: three characters per drawing
	call 04062h		;7e9a
	ld bc,00302h		;7e9d   ; Three wide by two high
	call 0490ch		;7ea0
L_7EA3:
	ld de,02018h		;7ea3   ; And the mouth, 0x20 to the right
	call boss_cell		;7ea6
	ret c			;7ea9
	ld de,07f62h		;7eaa
	ld a,(0e786h)		;7ead   ; 0xE786: the face that is due
	add a,a			;7eb0
	ld c,a			;7eb1
	add a,a			;7eb2
	add a,c			;7eb3
	call 04062h		;7eb4
	ld bc,00302h		;7eb7
	jp 0490ch		;7eba
boss_cell:		; The boss's position plus the offset that DE brings
	ld a,(0e783h)		;7ebd   ; The boss's row (0xE783) and its column (0xE785), plus whatever DE brings
	add a,e			;7ec0
	ld l,a			;7ec1
	ld a,(0e785h)		;7ec2
	add a,d			;7ec5
	ld h,a			;7ec6
	ret			;7ec7
erase_boss:		; Erases the 0x0B by 8 rectangle of the body
	ld a,(0e780h)		;7ec8   ; Only with 0xE780 at one
