	call 08100h		;7fb9
	call 08073h		;7fbc
	di			;7fbf   ; Bank 3 put back
	ld a,003h		;7fc0
	ld (0a000h),a		;7fc2
	ld (0f0f3h),a		;7fc5
	ei			;7fc8
	ld a,(0e117h)		;7fc9   ; 0xE117: the boss is already moving
	and a			;7fcc
	ret z			;7fcd
	ld a,(0e790h)		;7fce   ; Until both cells are zero, it carries on
	ld hl,0e7c0h		;7fd1   ; And 0xE7C0
	or (hl)			;7fd4
	ret nz			;7fd5
	jr L_7FA4		;7fd6
end_stage_5_boss:		; 0xE150 to one
	ld a,001h		;7fd8
	ld (0e150h),a		;7fda
	ret			;7fdd
start_or_advance:		; Past distance 0x1A0 it switches on 0xE117; if not, every 0xC0 frames it advances the script in 0xE116
	ld hl,(0e063h)		;7fde
	ld de,001a0h		;7fe1   ; Distance 0x1A0
	rst 20h			;7fe4
	jr c,L_7FED		;7fe5
	ld a,001h		;7fe7
	ld (0e117h),a		;7fe9
	ret			;7fec
L_7FED:
	ld hl,0e153h		;7fed   ; 0xE153: the frames left
	dec (hl)			;7ff0
	ret nz			;7ff1
	ld (hl),0c0h		;7ff2   ; Another 0xC0
	ld hl,0e116h		;7ff4
	ld a,(hl)			;7ff7
	inc (hl)			;7ff8
	and 00fh		;7ff9   ; Sixteen steps round and round
	ld c,a			;7ffb
	ld b,000h		;7ffc

; ----------------------------------------------------------------------
; DATA split_instruction: The first two bytes of an `ld hl,0x8041` whose third
;   byte (the 0x80) is the FIRST byte of bank 2. The instruction only exists
;   when bank 1 is at 0x6000 and bank 2 at 0x8000, which is how INIT always
;   maps them. They are listed as bytes because this listing ends at 0x7FFF.
;   0x7ffe..0x8000  (2 bytes)

; ----------------------------------------------------------------------
; THE LAST INSTRUCTION IS SPLIT BETWEEN THIS BANK AND THE NEXT
; ----------------------------------------------------------------------
DATA_split_instruction:
	defb 021h,041h	; 7ffe
